mrb_value
mrb_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value clone;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }

  if (mrb_singleton_class(mrb_class(self))) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  clone = mrb_obj_dup(mrb, self);
  mrb_iv_copy(mrb, mrb_obj_value(mrb_data_object_clone(mrb_obj_ptr(clone)), mrb_obj_ptr(self));
  if (mrb_obj_flag_frozen(mrb, self)) {
    mrb_obj_freeze(mrb, clone);
  }

  return clone;
}

mrb_value
clone_mrb_object(mrb_state *mrb, mrb_value self)
{
  mrb_value obj;
  struct RClass *c;
  mrb_bool frozen;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }

  c = mrb_obj_class(mrb, self);
  obj = mrb_obj_value(mrb_class_new_instance(mrb, 0, NULL, c));

  if (mrb_singleton_class_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  mrb_obj_clone(mrb, obj, self);

  frozen = mrb_obj_is_frozen(self);
  if (frozen) {
    mrb_obj_freeze(mrb, obj);
  }

  return obj;
}

mrb_value
mrb_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value clone;
  mrb_value klass;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }

  if (mrb_obj_singleton_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  klass = mrb_obj_class(mrb, self);
  clone = mrb_obj_alloc(mrb, mrb_class_real(klass), klass);

  mrb_data_object_dup(mrb, clone, self);
  mrb_obj_set_instance_variable(mrb, clone, "@__clone__", self);

  if (mrb_obj_frozen_p(self)) {
    mrb_obj_freeze(mrb, clone);
  }

  return clone;
}

mrb_value
mrb_obj_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value copy;
  mrb_value v;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate");
  }
  if (mrb_singleton_class(mrb, self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton");
  }
  copy = mrb_obj_alloc(mrb, mrb_obj_class(self), mrb_obj_iv_tbl(self));
  if (mrb_obj_singleton_class_p(self)) {
    mrb_value sc = mrb_get_iv_copy(mrb, self, mrb_intern_lit(mrb, "__klass__"));
    mrb_set_iv(mrb, copy, mrb_intern_lit(mrb, "__klass__"), sc);
  }
  mrb_obj_init_copy(mrb, copy, self);
  mrb_gc_register(mrb, &copy);
  if (mrb_obj_frozen_p(self)) {
    mrb_obj_freeze(mrb, copy);
  }
  return copy;
}

